//! Oracle test for G9 — Narrow, hardened `data_dir_guard` relaxation for
//! literal text.
//!
//! **FROZEN after Phase 0.** Do NOT edit this file after the initial commit.
//!
//! Phase 0: run on base `92367ec` and confirm RED at assertions 1–3
//! (positive cases currently blocked but should be allowed after the fix).
//! Bypass cases 4–11 must remain Blocked on both base and after the fix.

#![allow(clippy::unwrap_used, clippy::expect_used)]

mod common;

use aaf_hook::Decision;
use common::Fixture;

fn fixture() -> Fixture {
    Fixture::new()
}

fn is_allowed(d: &Decision) -> bool {
    matches!(d, Decision::Allow)
}

fn is_blocked(d: &Decision) -> bool {
    matches!(d, Decision::Deny(_))
}

// ── Positive cases: currently blocked → after the fix must be Allowed ────────

/// 1. `cat > note.md <<'EOF'\nmention AAF_DATA_DIR here\nEOF\n`
///    Single-command script, quoted delimiter, plain `cat` with output
///    redirect to a safe path → body is literal data, not code.
#[test]
fn pos1_cat_heredoc_quoted_writing_note() {
    let f = fixture();
    let d = f.bash("cat > note.md <<'EOF'\nmention AAF_DATA_DIR here\nEOF\n");
    assert!(
        is_allowed(&d),
        "pos1 expected Allowed, got {d:?}\n\
         (cat > note.md <<'EOF' with AAF_DATA_DIR literal in body should be allowed)"
    );
}

/// 2. `git commit -F - <<'EOF'\ndocs: explain AAF_DATA_DIR\nEOF\n`
///    Single-command script, quoted heredoc delimiter, body fed via `-F -` →
///    body is a literal commit message, not code.
#[test]
fn pos2_git_commit_heredoc_file_stdin() {
    let f = fixture();
    let d = f.bash("git commit -F - <<'EOF'\ndocs: explain AAF_DATA_DIR\nEOF\n");
    assert!(
        is_allowed(&d),
        "pos2 expected Allowed, got {d:?}\n\
         (git commit -F - <<'EOF' with AAF_DATA_DIR literal in body should be allowed)"
    );
}

/// 3. `git commit -m 'docs: explain AAF_DATA_DIR'`
///    Static literal string passed to `-m` → not a path, just a message.
#[test]
fn pos3_git_commit_static_message() {
    let f = fixture();
    let d = f.bash("git commit -m 'docs: explain AAF_DATA_DIR'");
    assert!(
        is_allowed(&d),
        "pos3 expected Allowed, got {d:?}\n\
         (git commit -m 'docs: explain AAF_DATA_DIR' with static message should be allowed)"
    );
}

// ── Bypass vectors: MUST stay Blocked on base AND after the fix ───────────────

/// 4. `bash <<'EOF'\ncat $AAF_DATA_DIR/receipt.key\nEOF\n`
///    Shell reads the heredoc body as a script → body executes, BLOCKED.
#[test]
fn bypass4_bash_reads_heredoc_body() {
    let f = fixture();
    let d = f.bash("bash <<'EOF'\ncat $AAF_DATA_DIR/receipt.key\nEOF\n");
    assert!(
        is_blocked(&d),
        "bypass4 must stay Blocked, got {d:?}\n\
         (bash <<'EOF' body is executable, must remain blocked)"
    );
}

/// 5. `eval "$(cat <<EOF\ncat $AAF_DATA_DIR/receipt.key\nEOF\n)"`
///    eval executes the substitution → BLOCKED.
#[test]
fn bypass5_eval_cat_heredoc() {
    let f = fixture();
    // Note: unquoted <<EOF so shell expands inside; eval runs the result.
    let d = f.bash("eval \"$(cat <<EOF\ncat $AAF_DATA_DIR/receipt.key\nEOF\n)\"");
    assert!(
        is_blocked(&d),
        "bypass5 must stay Blocked, got {d:?}\n\
         (eval with cat heredoc body must remain blocked)"
    );
}

/// 6. `python3 - <<'EOF'\nimport os; print(os.environ['AAF_DATA_DIR'])\nEOF\n`
///    python3 reads stdin as a script → BLOCKED.
#[test]
fn bypass6_python3_reads_heredoc_body() {
    let f = fixture();
    let d = f.bash("python3 - <<'EOF'\nimport os; print(os.environ['AAF_DATA_DIR'])\nEOF\n");
    assert!(
        is_blocked(&d),
        "bypass6 must stay Blocked, got {d:?}\n\
         (python3 reading stdin heredoc must remain blocked)"
    );
}

/// 7. `cat > /tmp/x.sh <<'EOF'\ncat $AAF_DATA_DIR/receipt.key\nEOF\n && bash /tmp/x.sh`
///    Multi-command script (&&) → NOT a single-command script → BLOCKED.
#[test]
fn bypass7_cat_heredoc_then_bash() {
    let f = fixture();
    let d =
        f.bash("cat > /tmp/x.sh <<'EOF'\ncat $AAF_DATA_DIR/receipt.key\nEOF\n && bash /tmp/x.sh");
    assert!(
        is_blocked(&d),
        "bypass7 must stay Blocked, got {d:?}\n\
         (multi-command: cat heredoc && bash must remain blocked)"
    );
}

/// 8. `cat <<'EOF' | bash\ncat $AAF_DATA_DIR/receipt.key\nEOF\n`
///    cat is piped to bash → not a data-only context → BLOCKED.
#[test]
fn bypass8_cat_heredoc_pipe_bash() {
    let f = fixture();
    let d = f.bash("cat <<'EOF' | bash\ncat $AAF_DATA_DIR/receipt.key\nEOF\n");
    assert!(
        is_blocked(&d),
        "bypass8 must stay Blocked, got {d:?}\n\
         (cat <<'EOF' | bash must remain blocked)"
    );
}

